    trialF          : REAL;
    resetRising     : BOOL;
    modeChanged     : BOOL;
    isFaultCondition: BOOL;
END_VAR

eT := tempSP - tempPV;

resetRising := resetBtn AND NOT prevResetBtn;
modeChanged := (prevMode <> 16) AND (mode <> prevMode);
isFaultCondition := (mode < 0) OR (mode > 2) OR (scanSeconds <= 0.0) OR (scanSeconds > 10.0);

fault := isFaultCondition;
normalMode := NOT isFirstScan AND NOT isFaultCondition AND NOT resetRising AND NOT modeChanged;

IF isFirstScan THEN
    flowSP := manualFlowSP;
    valveCommand := manualValve;
    accT := 0.0;
    accF := 0.0;
    isFirstScan := FALSE;

ELSIF resetRising THEN
    flowSP := manualFlowSP;
    valveCommand := manualValve;
    accT := 0.0;
    accF := 0.0;

ELSIF isFaultCondition THEN
    flowSP := manualFlowSP;
    valveCommand := manualValve;
    accT := 0.0;
    accF := 0.0;

ELSIF modeChanged THEN
    IF mode = 2 THEN
        flowSP := prevFlowSP;
        valveCommand := prevValveCommand;
    ELSE
        flowSP := manualFlowSP;
        valveCommand := prevValveCommand;
    END_IF

ELSIF normalMode THEN
    IF mode = 0 THEN
        flowSP := manualFlowSP;
        valveCommand := manualValve;
    ELSE
        trialT := accT + 0.2 * eT * scanSeconds;
        flowSP := 1.0 * eT + trialT;
        IF flowSP > 50.0 THEN
            flowSP := 50.0;
        ELSIF flowSP < 0.0 THEN
            flowSP := 0.0;
        END_IF;
        accT := flowSP - 1.0 * eT;

        eF := flowSP - flowPV;
        trialF := accF + 0.5 * eF * scanSeconds;
        valveCommand := 2.0 * eF + trialF;
        IF valveCommand > 100.0 THEN
            valveCommand := 100.0;
        ELSIF valveCommand < 0.0 THEN
            valveCommand := 0.0;
        END_IF;
        accF := valveCommand - 2.0 * eF;

        IF mode = 0 THEN
            flowSP := manualFlowSP;
            valveCommand := manualValve;
        END_IF;
    END_IF;

ELSE
    flowSP := prevFlowSP;
    valveCommand := prevValveCommand;
END_IF;

prevResetBtn := resetBtn;
prevMode := mode;
prevFlowSP := flowSP;
prevValveCommand := valveCommand;

